extends Node
class_name DungeonGenerator

@export var seed_val: int = 12345
@export var width: int = 64
@export var height: int = 64
@export var wall_threshold: float = 0.0

var _rooms: Array[Rect2i] = []

func generate(target: TileMapLayer) -> void:
	target.clear()
	_rooms = []
	var noise = FastNoiseLite.new()
	noise.seed = seed_val

	# Base terrain
	for x in range(width):
		for y in range(height):
			var val = noise.get_noise_2d(x, y)
			if x == 0 or x == width - 1 or y == 0 or y == height - 1:
				target.set_cell(Vector2i(x, y), 1, Vector2i(1, 0))
				continue
			if val < wall_threshold:
				target.set_cell(Vector2i(x, y), 0, Vector2i(0, 0))
			else:
				target.set_cell(Vector2i(x, y), 1, Vector2i(1, 0))

	# Carve rooms
	_rooms = []
	var rng = RandomNumberGenerator.new()
	rng.seed = seed_val
	for i in range(3):
		var rw = rng.randi_range(6, 12)
		var rh = rng.randi_range(6, 12)
		var rx = rng.randi_range(1, width - 2 - rw)
		var ry = rng.randi_range(1, height - 2 - rh)
		var r = Rect2i(rx, ry, rw, rh)
		var overlap = false
		for er in _rooms:
			if r.intersects(er):
				overlap = true
				break
		if !overlap:
			_rooms.append(r)
			for tx in range(r.position.x, r.end.x):
				for ty in range(r.position.y, r.end.y):
					target.set_cell(Vector2i(tx, ty), 0, Vector2i(0, 0))

	# Connect rooms
	for i in range(_rooms.size() - 1):
		var r1 = _rooms[i]
		var r2 = _rooms[i+1]
		var p1 = r1.get_center()
		var p2 = r2.get_center()
		# L-shaped corridor: horizontal then vertical
		for x in range(min(p1.x, p2.x), max(p1.x, p2.x) + 1):
			target.set_cell(Vector2i(x, p1.y), 0, Vector2i(0, 0))
		for y in range(min(p1.y, p2.y), max(p1.y, p2.y) + 1):
			target.set_cell(Vector2i(p2.x, y), 0, Vector2i(0, 0))

func count_floor_tiles(target: TileMapLayer) -> int:
	var count = 0
	var ur = target.get_used_rect()
	for x in range(ur.position.x, ur.end.x):
		for y in range(ur.position.y, ur.end.y):
			if target.get_cell_source_id(Vector2i(x, y)) == 0:
				count += 1
	return count

func find_rooms() -> Array[Rect2i]:
	return _rooms
EOF
